# 商品价格展示：按价格从低到高排序。


def cheapest_first(prices):
    """返回价格升序的新列表。"""
    return sorted(prices, reverse=True)

verification_tests:
from target import cheapest_first


def test_single_price():
    assert cheapest_first([5]) == [5]


def test_empty_prices():
    assert cheapest_first([]) == []


def test_ascending_order():
    assert cheapest_first([3, 1, 2]) == [1, 2, 3]
